import { useState } from "react";
import React from "react";
import AddTaskModal from "./AddTaskModal";
import EditTaskModal from "./EditTaskModal";
import api from "../services/api";

interface Task{
    id: number;
    text: string;
    priority: "High" | "Medium" | "Low";
    doneFlag: boolean;
    dueDate?: string;
    creationDate: string;
}

interface TaskListProps{
    tasks: Task[];
    markTaskAsDone: (id: number) => void;
    onTaskAdded: () => void;
    onTaskUpdated: () => void;
    onTaskDeleted: () => void;
    fetchTasks: (filteredTasks?: Task[]) => void;
}

const TaskList: React.FC<TaskListProps> = ({ tasks, markTaskAsDone, onTaskAdded, onTaskUpdated, onTaskDeleted, fetchTasks }) => {
    const [showAddModal, setShowAddModal] = useState(false);
    const [taskToEdit, setTaskToEdit] = useState<Task | null>(null);

    const [sortBy, setSortBy] = useState<string | null>(null);
    const[sortOrder, setSortOrder] = useState<string>("asc");




    const [filterText, setFilterText] = useState("");
    const [filterPriority, setFilterPriority] = useState("");
    const [filterDone, setFilterDone] = useState("");

    const fetchFilteredTasks = async () => {
        try{
            const response = await api.get("/tasks/filter", {
                params: {
                    filterByText: filterText || undefined,
                    filterByPriority: filterPriority || undefined,
                    filterByDoneFlag: filterDone === "" ? undefined : filterDone === "true",
                },
            });

            fetchTasks(response.data);

        }catch(error) {
            console.error("Error fetching filtered tasks", error);
        }
    };

    const deleteTask = async (id: number) => {
        const confirmDelete = window.confirm("Are you sure you want to delete this task?");
        if(!confirmDelete) return;

        try{
            await api.delete(`/tasks/${id}`);
            onTaskDeleted();
        }catch(error) {
            console.error("Error deleting task: ", error);
            alert("There was an error deleting the task");
        }
    };

    return(
        <div>
            <button onClick={() => setShowAddModal(true)}>New Task</button>

            {showAddModal && <AddTaskModal onClose={() => setShowAddModal(false)} onTaskAdded={onTaskAdded} />}

            {taskToEdit && (
                <EditTaskModal
                    task = {taskToEdit}
                    onClose = {() => setTaskToEdit(null)}
                    onTaskUpdated = {onTaskUpdated}
                />
            )}

            <h2>Task List</h2>

            <div>
                <input
                    type = "text"
                    placeholder = "Search by name..."
                    value = {filterText}
                    onChange = {(e) => setFilterText(e.target.value)}
                />
                <select value={filterPriority} onChange={(e) => setFilterPriority(e.target.value)}>
                    <option value="">All Priorities</option>
                    <option value="High">High</option>
                    <option value="Medium">Medium</option>
                    <option value="Low">Low</option>
                </select>

                <select value={filterDone} onChange={(e) => setFilterDone(e.target.value)}>
                    <option value="">All</option>
                    <option value="true">Done</option>
                    <option value="false">undone</option>
                </select>

                <button onClick={fetchFilteredTasks}>Apply Filters</button>
            </div>





            {tasks.length === 0 ? (
                <p>No available tasks!</p>
            ) : (
                <ul>
                    {tasks.map((task) => (
                        <li key={task.id}>

                            <input
                                type = "checkbox"
                                checked = {task.doneFlag}
                                onChange = {() => markTaskAsDone(task.id)}
                            />

                            <strong style = {{ textDecoration: task.doneFlag ? "line-through" : "none" }}>
                                {task.text}
                            </strong>
                            {" - "}
                            {task.priority}

                            <button onClick={() => setTaskToEdit(task)}>Edit</button>
                            <button onClick={() => deleteTask(task.id)}>Delete</button>
                        </li>
                    ))}
                </ul>
            )}
        </div>
    );
};

export default TaskList;
